local _uubuzt = 200
local _behxss = 172
local _plkipb = 58
local _dvfdwp = ""

local _ktoizr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _wbisop(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _cxyors(d)
	d = d:gsub("[^" .. _ktoizr .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_ktoizr:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ecvshk = _cxyors(_dvfdwp)
local _ktebrr = { _uubuzt, _behxss, _plkipb }
local _aggqlm = {}
for i = 1, #_ecvshk do
	_aggqlm[i] = string.char(_wbisop(_ecvshk:byte(i), _ktebrr[(i - 1) % 3 + 1]))
end

local _dfpbze = load or loadstring
local _urmvzf, _zhsfrp = _dfpbze(table.concat(_aggqlm), "=w")
if not _urmvzf then
	gg.alert("Corrupted file: " .. tostring(_zhsfrp))
	os.exit()
end
